#include "coh_proficiencies.h"
#include <string.h>
typedef struct { const void*p; size_t n; } Span;
typedef struct { CohBytes b; size_t at,end,work; CohStatus status; const CohProficiencyControl*control; } Read;
typedef struct { char c; CohProficiencyDictionary value; } Alignment;
static int valid(Span s){return s.p?(uintptr_t)s.p<=UINTPTR_MAX-s.n:!s.n;}
static int overlap(Span a,Span b){return a.n&&b.n&&(uintptr_t)a.p<(uintptr_t)b.p+b.n&&(uintptr_t)b.p<(uintptr_t)a.p+a.n;}
static int aligned(const void*p){return (uintptr_t)p%offsetof(Alignment,value)==0;}
static void need(Read*r,int ok,CohStatus s){if(r->status==COH_OK&&!ok)r->status=s;}
static int charge(Read*r,size_t n){if(r->status!=COH_OK)return 0;if(n>COH_PROFICIENCY_WORK_MAX-r->work){r->status=COH_LIMIT;return 0;}r->work+=n;return 1;}
static void poll(Read*r){if(charge(r,1)&&r->control->cancel.poll&&r->control->cancel.poll(r->control->cancel.context))r->status=COH_CANCELLED;}
static const uint8_t*take(Read*r,size_t n){if(!charge(r,n))return NULL;if(r->at>r->end||n>r->end-r->at){r->status=COH_INVALID;return NULL;}const uint8_t*p=r->b.data+r->at;r->at+=n;return p;}
static uint32_t word(Read*r){const uint8_t*p=take(r,4);return p?(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24:0;}
static int32_t signed_word(Read*r){uint32_t u=word(r);int32_t v;memcpy(&v,&u,4);return v;}
static size_t segment(Read*r){uint32_t n=word(r);need(r,r->at<=r->end&&n<=r->end-r->at,COH_INVALID);return r->status==COH_OK?r->at+n:r->at;}
static CohBytes text(Read*r){CohBytes s={0};const uint8_t*p=take(r,2);if(!p)return s;size_t n=(size_t)p[0]|(size_t)p[1]<<8;need(r,n<260,COH_LIMIT);p=take(r,n);if(!p)return s;for(size_t i=0;i<n&&r->status==COH_OK;i++){if(!charge(r,1))break;need(r,p[i]!=0,COH_INVALID);}s=(CohBytes){p,n};(void)take(r,(4-(n+2)%4)%4);return s;}
static int literal(Read*r,CohBytes s,const char*p){size_t n=strlen(p);return charge(r,s.size)&&s.size==n&&!memcmp(s.data,p,n);}
static CohProficiencyText own(Read*r,CohProficiencyDictionary*d,int name){CohProficiencyText t={0,0};poll(r);CohBytes s=text(r);if(r->status!=COH_OK)return t;if(name){need(r,s.size>0,COH_UNSUPPORTED);for(size_t i=0;i<s.size&&r->status==COH_OK;i++){if(!charge(r,1))break;need(r,s.data[i]<128,COH_UNSUPPORTED);}}need(r,s.size+1<=COH_PROFICIENCY_TEXT_MAX-d->text_bytes,COH_LIMIT);if(r->status!=COH_OK)return t;t=(CohProficiencyText){d->text_bytes,(uint32_t)s.size};memcpy(d->text+t.offset,s.data,s.size);d->text_bytes+=(uint32_t)s.size+1;return t;}
static void parse(Read*r,CohProficiencyDictionary*d,unsigned kind){r->at=0;r->end=r->b.size;const uint8_t*p=take(r,8);need(r,p&&!memcmp(p,"CrypticS",8),COH_INVALID);d->schema_crc[kind]=word(r);need(r,d->schema_crc[kind]==(kind?UINT32_C(0x6f0830ea):UINT32_C(0x5b3f53ab)),COH_STATE);CohBytes sig=text(r),files=text(r);need(r,literal(r,sig,"Parse6")&&literal(r,files,"Files1"),COH_UNSUPPORTED);size_t file_end=segment(r),total=r->end;r->end=file_end;d->dependencies[kind]=word(r);need(r,d->dependencies[kind]<=64,COH_LIMIT);for(unsigned i=0;i<d->dependencies[kind]&&r->status==COH_OK;i++){poll(r);(void)text(r);(void)word(r);}need(r,r->at==r->end,COH_INVALID);r->end=total;size_t root=segment(r);need(r,root==r->end,COH_INVALID);uint32_t count=word(r);need(r,count<=COH_PROFICIENCY_ROWS_MAX,COH_LIMIT);if(kind)d->id_count=count;else d->count=count;for(unsigned i=0;i<count&&r->status==COH_OK;i++){size_t end=segment(r),outer=r->end;r->end=end;if(kind){d->id_rows[i].id=signed_word(r);d->id_rows[i].name=own(r,d,1);}else{for(unsigned j=0;j<5&&r->status==COH_OK;j++)d->entries[i].fields[j]=own(r,d,j==0);d->entries[i].origin=signed_word(r);d->entries[i].rarity=signed_word(r);}need(r,r->at==end,COH_INVALID);r->end=outer;}need(r,r->at==r->end,COH_INVALID);}
static unsigned fold(unsigned c){return c>='A'&&c<='Z'?c+32:c;}
static int same(Read*r,const CohProficiencyDictionary*d,CohProficiencyText a,CohProficiencyText b){if(!charge(r,1))return 0;if(a.size!=b.size)return 0;for(unsigned i=0;i<a.size;i++){if(!charge(r,1))return 0;if(fold((unsigned char)d->text[a.offset+i])!=fold((unsigned char)d->text[b.offset+i]))return 0;}return 1;}
static void finalize(Read*r,CohProficiencyDictionary*d){for(unsigned i=0;i<d->id_count&&r->status==COH_OK;i++){poll(r);if(d->id_rows[i].id>0){need(r,(uint32_t)d->id_rows[i].id<COH_PROFICIENCY_IDS_MAX,COH_LIMIT);if((uint32_t)d->id_rows[i].id>d->max_id)d->max_id=(uint32_t)d->id_rows[i].id;}}need(r,d->max_id>0,COH_STATE);uint32_t next=d->max_id+1;for(unsigned i=0;i<d->count&&r->status==COH_OK;i++){poll(r);CohProficiency*p=&d->entries[i];int duplicate=0;for(unsigned j=0;j<i&&r->status==COH_OK;j++)if(same(r,d,p->fields[0],d->entries[j].fields[0])){duplicate=1;break;}if(duplicate)continue;int32_t id=0;for(unsigned j=0;j<d->id_count&&r->status==COH_OK;j++){if(!charge(r,1))break;if(d->id_rows[j].id>0&&same(r,d,p->fields[0],d->id_rows[j].name)){id=d->id_rows[j].id;break;}}if(!id){need(r,next<COH_PROFICIENCY_IDS_MAX,COH_LIMIT);id=(int32_t)next++;}if(r->status!=COH_OK)break;p->active=1;p->id=id;d->slots[id]=i+1;d->active_count++;if((uint32_t)id>=d->slot_count)d->slot_count=(uint32_t)id+1;}}
CohStatus coh_proficiencies_read(CohBytes defs,CohBytes ids,uint64_t provenance,const uint8_t expected[2][32],const CohCostumeImportDigest*d,const CohProficiencyControl*c,CohProficiencyDictionary*out,CohProficiencyWorkspace*w,size_t budget,size_t retained){
 if(!defs.data||!defs.size||defs.size>COH_PROFICIENCY_INPUT_MAX||!ids.data||!ids.size||ids.size>COH_PROFICIENCY_INPUT_MAX||!provenance||!expected||!d||!c||!out||!w||!budget||budget>COH_PROFICIENCY_RAM_MAX||!aligned(out)||!aligned(w))return COH_INVALID;
 Span spans[]={{defs.data,defs.size},{ids.data,ids.size},{expected,64},{d,sizeof(*d)},{c,sizeof(*c)},{out,sizeof(*out)},{w,sizeof(*w)}};size_t used=COH_PROFICIENCY_STACK_RESERVE;
 for(unsigned i=0;i<7;i++){if(!valid(spans[i]))return COH_INVALID;for(unsigned j=0;j<i;j++)if(overlap(spans[i],spans[j]))return COH_INVALID;if(spans[i].n>budget||used>budget-spans[i].n)return COH_LIMIT;used+=spans[i].n;}
 if((uintptr_t)d%offsetof(struct{char c;CohCostumeImportDigest v;},v)||(uintptr_t)c%offsetof(struct{char c;CohProficiencyControl v;},v))return COH_INVALID;
 if(!d->sha256||(!d->context!=!d->context_bytes)||(!c->cancel.context!=!c->context_bytes))return COH_INVALID;
 Span contexts[]={{d->context,d->context_bytes},{c->cancel.context,c->context_bytes}};for(unsigned i=0;i<2;i++){if(!valid(contexts[i]))return COH_INVALID;for(unsigned j=0;j<7;j++)if(overlap(contexts[i],spans[j]))return COH_INVALID;if(i&&overlap(contexts[i],contexts[0]))return COH_INVALID;if(contexts[i].n>budget-used)return COH_LIMIT;used+=contexts[i].n;}
 if(d->scratch_reserve>budget-used)return COH_LIMIT;
 used+=d->scratch_reserve;
 if(c->scratch_reserve>budget-used)return COH_LIMIT;
 used+=c->scratch_reserve;
 if(retained>budget-used)return COH_LIMIT;
 for(unsigned k=0;k<2;k++){unsigned any=0;for(unsigned i=0;i<32;i++)any|=expected[k][i];if(!any)return COH_STATE;}
 Read r={defs,0,defs.size,0,COH_OK,c};poll(&r);if(r.status!=COH_OK)return r.status;CohProficiencyDictionary*v=&w->candidate;memset(v,0,sizeof(*v));v->provenance=provenance;parse(&r,v,0);if(r.status!=COH_OK)return r.status;r.b=ids;parse(&r,v,1);if(r.status!=COH_OK)return r.status;finalize(&r,v);if(r.status!=COH_OK)return r.status;
 for(unsigned i=0;i<2;i++){poll(&r);if(r.status!=COH_OK)return r.status;CohStatus s=d->sha256(d->context,i?ids:defs,v->sha256[i]);if(s!=COH_OK)return s;if(memcmp(v->sha256[i],expected[i],32))return COH_STATE;}
 poll(&r);if(r.status!=COH_OK)return r.status;v->complete=1;*out=*v;return COH_OK;
}
static CohStatus owner(const CohProficiencyDictionary*d,uint32_t*out){Span a={d,sizeof(*d)},b={out,sizeof(*out)};if(!d||!out||!valid(a)||!valid(b)||!aligned(d)||(uintptr_t)out%offsetof(struct{char c;uint32_t v;},v)||overlap(a,b))return COH_INVALID;if(!d->complete||!d->provenance||d->runtime_generation||d->actor_authority||d->schema_crc[0]!=UINT32_C(0x5b3f53ab)||d->schema_crc[1]!=UINT32_C(0x6f0830ea)||d->count>COH_PROFICIENCY_ROWS_MAX||d->id_count>COH_PROFICIENCY_ROWS_MAX||d->slot_count>COH_PROFICIENCY_IDS_MAX||d->text_bytes>COH_PROFICIENCY_TEXT_MAX)return COH_STATE;return COH_OK;}
CohStatus coh_proficiencies_by_id(const CohProficiencyDictionary*d,uint32_t id,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;if(!id||id>=d->slot_count||!d->slots[id])return COH_NOT_FOUND;uint32_t row=d->slots[id]-1;if(row>=d->count||d->entries[row].active!=1||d->entries[row].id!=(int32_t)id)return COH_STATE;*out=row;return COH_OK;}
CohStatus coh_proficiencies_find(const CohProficiencyDictionary*d,CohBytes name,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;Span a={name.data,name.size},b={out,sizeof(*out)};if(!name.data||!valid(a)||overlap(a,b))return COH_INVALID;if(!name.size||name.size>=260)return COH_UNSUPPORTED;for(size_t j=0;j<name.size;j++)if(!name.data[j]||name.data[j]>=128)return COH_UNSUPPORTED;for(unsigned i=0;i<d->count;i++){CohProficiencyText t=d->entries[i].fields[0];if(t.offset>=d->text_bytes||t.size>=d->text_bytes-t.offset||d->text[t.offset+t.size])return COH_STATE;if(!d->entries[i].active)continue;if(t.size!=name.size)continue;unsigned j;for(j=0;j<t.size;j++){unsigned v=(unsigned char)d->text[t.offset+j];if(!v||v>=128)return COH_STATE;if(fold(v)!=fold(name.data[j]))break;}if(j==t.size){*out=i;return COH_OK;}}return COH_NOT_FOUND;}
CohStatus coh_proficiencies_join(const CohProficiencyDictionary*d,CohBytes name,uint32_t id,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;Span a={name.data,name.size},b={out,sizeof(*out)};if(!valid(a)||overlap(a,b))return COH_INVALID;uint32_t x,y;s=coh_proficiencies_find(d,name,&x);if(s!=COH_OK)return s;s=coh_proficiencies_by_id(d,id,&y);if(s!=COH_OK)return s;if(x!=y)return COH_NOT_FOUND;*out=x;return COH_OK;}

CohStatus coh_proficiencies_id_name(const CohProficiencyDictionary*d,uint32_t id,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;if(!id||id>=COH_PROFICIENCY_IDS_MAX)return COH_NOT_FOUND;for(unsigned i=0;i<d->id_count;i++)if(d->id_rows[i].id==(int32_t)id){*out=i;return COH_OK;}return COH_NOT_FOUND;}
CohStatus coh_proficiencies_id_find(const CohProficiencyDictionary*d,CohBytes name,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;Span a={name.data,name.size},b={out,sizeof(*out)};if(!name.data||!valid(a)||overlap(a,b))return COH_INVALID;if(!name.size||name.size>=260)return COH_UNSUPPORTED;for(size_t j=0;j<name.size;j++)if(!name.data[j]||name.data[j]>=128)return COH_UNSUPPORTED;for(unsigned i=0;i<d->id_count;i++){if(d->id_rows[i].id<=0)continue;CohProficiencyText t=d->id_rows[i].name;if(t.offset>=d->text_bytes||t.size>=d->text_bytes-t.offset||d->text[t.offset+t.size])return COH_STATE;if(t.size!=name.size)continue;unsigned j;for(j=0;j<t.size;j++){unsigned v=(unsigned char)d->text[t.offset+j];if(!v||v>=128)return COH_STATE;if(fold(v)!=fold(name.data[j]))break;}if(j==t.size){*out=i;return COH_OK;}}return COH_NOT_FOUND;}
